STAGE_ALIAS_REPAIRED_SOURCE="def stage_aliases():\n paths=[ROOT/'android-native-device-api35.lease',ROOT/'android-native-device-android-api35.lease',ROOT/'android-native-device-api35-0dd55704-1e80-4d62-8d9d-2f0a123e0c3b.release-intent',ROOT/'android-native-device-android-api35-0dd55704-1e80-4d62-8d9d-2f0a123e0c3b.release-intent']\n result=[];STAGE_ALIAS_READS.append(result)\n for path in paths:\n  chain,name=parent_fds(path)\n  try:\n   guard_parents(chain)\n   try:os.stat(name,dir_fd=chain[-1]['fd'],follow_symlinks=False);present=True\n   except FileNotFoundError:present=False\n   if present:\n    fact=read_fixed(path,1024);raw=fact['raw'];gen=fact['generation']\n    # Exact census FP9 -> bundle descriptor9 projection, including full size.\n    pin={'generation':[gen[i]for i in (0,1,5,6,7,8,2,3,4)],'sha256':fact['sha256'],'parents':{}}\n    route=pathlib.Path('/')\n    for number,parent in enumerate(chain):\n     if number:route=route/parent['name']\n     value=parent['pin'];pin['parents'][str(route)]=[value[i]for i in (0,1,5,6,7)]\n    result.append({'path':str(path),'state':'present','pin':pin,'rawBase64':STAGE_BASE64.b64encode(raw).decode()})\n    if type(gen)is not list or len(gen)!=9 or any(type(n)is not int for n in gen)or gen[6:9]!=[1000,1000,1]or gen[5]!=0o100600 or fact['hashScope']!='full'or gen[2]!=len(raw)or len(raw)>1024:raise ValueError('stage_diagnostic_alias_changed')\n   else:result.append({'path':str(path),'state':'absent'})\n   guard_parents(chain)\n  finally:close_parents(chain)\n lease=result[0]\n if lease['state']!='present'or lease['pin']['sha256']!='44f2b1d325cbd0dedda6d6af5b1bf856792edf327accad99475e8cde6e4e865a'or any(item['state']!='absent'for item in result[1:]):raise ValueError('stage_diagnostic_alias_changed')\n return result\n"
