STAGE_ADMISSION_COMPOSE_STAGE_GUARD_SOURCE='def compose_stage_guard(program,alias_raw):\n source_tree=ast.parse(alias_raw);literal=next(n for n in source_tree.body if isinstance(n,ast.Assign)and any(isinstance(t,ast.Name)and t.id==\'REMOTE\'for t in n.targets))\n stage=ast.literal_eval(literal.value);stage_tree=ast.parse(stage)\n node=next(n for n in stage_tree.body if isinstance(n,ast.FunctionDef)and n.name==\'stage_aliases\')\n alias=ast.get_source_segment(stage,node).replace(\'STAGE_BASE64\',\'BASELINE_BASE64\')\n closure="STAGE_ALIAS_READS=[]\\nSTAGE_ADMISSION_ALIAS_PIN=None\\n"+alias+"\\ndef component_stage_alias_guard():\\n global STAGE_ADMISSION_ALIAS_PIN\\n if len(STAGE_ALIAS_READS)>=256:raise ValueError(\'component_stage_alias_inventory_limit\')\\n value=stage_aliases()\\n if STAGE_ADMISSION_ALIAS_PIN is None:STAGE_ADMISSION_ALIAS_PIN=value\\n elif value!=STAGE_ADMISSION_ALIAS_PIN:raise ValueError(\'component_stage_alias_changed\')\\n"\n marker=\'def claim_inventory():\'\n if program.count(marker)!=1:raise ValueError(\'component_stage_alias_factory_changed\')\n program=program.replace(marker,closure+\'\\n\'+marker)\n marker=\'  def current():\\n   certificate_guard();guard()\'\n if program.count(marker)!=1:raise ValueError(\'component_stage_alias_factory_changed\')\n program=program.replace(marker,marker+\'\\n   component_stage_alias_guard()\')\n marker="\'componentRetirementRows\':component_retirement_rows,"\n if program.count(marker)!=1:raise ValueError(\'component_stage_alias_factory_changed\')\n program=program.replace(marker,marker+"\'componentStageAliasReads\':STAGE_ALIAS_READS,")\n tree=ast.parse(program);names={\'getter_stage\',\'read_fixed\',\'parent_fds\',\'guard_parents\',\'facts\',\'tree_facts\',\'getter_generation\',\'getter_apk\',\'getter_binary\',\'getter_adb\',\'command_host_guard\',\'external_jdk_guard\',\'stage_aliases\',\'component_stage_alias_guard\'};codes=set()\n for node in tree.body:\n  if isinstance(node,ast.FunctionDef)and node.name in names:\n   for call in ast.walk(node):\n    if isinstance(call,ast.Call)and isinstance(call.func,ast.Name)and call.func.id==\'ValueError\'and len(call.args)==1 and isinstance(call.args[0],ast.Constant)and type(call.args[0].value)is str:codes.add(call.args[0].value)\n changes=[]\n for name,values in [(\'KNOWN_FAILURE_CODES\',codes),(\'KNOWN_FAILURE_FUNCTIONS\',names)]:\n  rows=[n for n in tree.body if isinstance(n,ast.Assign)and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)and n.targets[0].id==name]\n  if len(rows)!=1:raise ValueError(\'component_stage_alias_factory_changed\')\n  n=rows[0];previous=ast.literal_eval(n.value);changes.append((n.lineno-1,n.end_lineno,name+\'=\'+repr(tuple(sorted(set(previous)|values)))+\'\\n\'))\n lines=program.splitlines(True)\n for start,end,text in sorted(changes,reverse=True):lines[start:end]=[text]\n return \'\'.join(lines)'

STAGE_ADMISSION_VALIDATE_STAGE_ALIASES_SOURCE="def validate_stage_aliases(proof,state):\n names=['android-native-device-api35.lease','android-native-device-android-api35.lease','android-native-device-api35-0dd55704-1e80-4d62-8d9d-2f0a123e0c3b.release-intent','android-native-device-android-api35-0dd55704-1e80-4d62-8d9d-2f0a123e0c3b.release-intent']\n reads=proof.get('componentStageAliasReads')\n if type(reads)is not list or not 2<=len(reads)<=256:raise ValueError('component_stage_alias_projection_unknown')\n for rows in reads:\n  if type(rows)is not list or len(rows)!=4 or rows!=reads[0]:raise ValueError('component_stage_alias_projection_unknown')\n  for i,row in enumerate(rows):\n   path=Path(REMOTE_ROOT)/names[i]\n   if type(row)is not dict or row.get('path')!=str(path)or row.get('state')!=('present'if i==0 else 'absent'):raise ValueError('component_stage_alias_projection_unknown')\n   if i:\n    if set(row)!={'path','state'}:raise ValueError('component_stage_alias_projection_unknown')\n    continue\n   if set(row)!={'path','state','pin','rawBase64'}or type(row['pin'])is not dict or set(row['pin'])!={'generation','sha256','parents'}:raise ValueError('component_stage_alias_projection_unknown')\n   raw=base64.b64decode(row['rawBase64'],validate=True);pin=row['pin'];g=pin['generation']\n   if len(raw)!=121 or hashlib.sha256(raw).hexdigest()!='44f2b1d325cbd0dedda6d6af5b1bf856792edf327accad99475e8cde6e4e865a'or pin['sha256']!=hashlib.sha256(raw).hexdigest()or type(g)is not list or len(g)!=9 or any(type(n)is not int for n in g)or g[0]<0 or g[1]<=0 or g[2:7]!=[0o100600,1000,1000,1,len(raw)]or any(n<=0 for n in g[7:]):raise ValueError('component_stage_alias_projection_unknown')\n   parents=pin['parents'];expected={str(v)for v in path.parents}\n   if type(parents)is not dict or set(parents)!=expected:raise ValueError('component_stage_alias_projection_unknown')\n   for value in parents.values():\n    if type(value)is not list or len(value)!=5 or any(type(n)is not int for n in value)or value[0]<0 or value[1]<=0 or not stat.S_ISDIR(value[2])or any(n<0 for n in value[3:]):raise ValueError('component_stage_alias_projection_unknown')"
