CLOSING_ROUTE_READERS_SOURCE='def _pin(info):\n    return [info.st_dev, info.st_ino, info.st_mode, info.st_uid, info.st_gid,\n            info.st_nlink, info.st_size, info.st_mtime_ns, info.st_ctime_ns]\n\ndef _parents(path):\n    """Descriptor pins for every absolute parent, refusing symlinks."""\n    if (os.name!=\'posix\' or not all(callable(getattr(os,name,None)) for name in (\'getuid\',\'geteuid\',\'getgid\',\'getegid\',\'getgroups\')) or\n        not all(hasattr(os,name) for name in (\'O_DIRECTORY\',\'O_NOFOLLOW\'))):\n        raise ValueError(\'component_bundle_posix_fd_required\')\n    path=Path(path).absolute(); chain=[]\n    try:\n        fd=os.open(\'/\', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)\n        chain.append((\'/\',fd))\n        for part in path.parts[1:]:\n            fd=os.open(part,os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,dir_fd=chain[-1][1])\n            chain.append((str(Path(chain[-1][0])/part),fd))\n        pins={name:_pin(os.fstat(fd))[:5] for name,fd in chain}\n        for name,fd in chain:\n            if _pin(os.stat(name,follow_symlinks=False))[:5]!=pins[name]:\n                raise ValueError(\'component_bundle_parent_changed\')\n        return chain,pins\n    except BaseException:\n        for _,fd in reversed(chain):os.close(fd)\n        raise\n\ndef _close(chain):\n    for _,fd in reversed(chain):os.close(fd)'

CLOSING_ROUTE_CLAIM_RECORD_SOURCE="def claim_record(path,limit=4194304):\n chain,parents=COMPONENT_BUNDLE._parents(path.parent);fd=None\n try:\n  parent=os.fstat(chain[-1][1])\n  if parent.st_uid not in (0,1000) or parent.st_gid not in (0,1000) or stat.S_IMODE(parent.st_mode)!=0o700:raise ValueError('claim_parent_unsafe')\n  try:fd=os.open(path.name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK,dir_fd=chain[-1][1])\n  except FileNotFoundError:\n   # Positive named absence is checked twice under the same held parent.\n   try:os.stat(path.name,dir_fd=chain[-1][1],follow_symlinks=False)\n   except FileNotFoundError:return {'path':str(path),'state':'absent','parents':parents}\n   raise ValueError('claim_absence_changed')\n  before=COMPONENT_BUNDLE._pin(os.fstat(fd));raw=bytearray()\n  if not stat.S_ISREG(before[2]) or before[3] not in (0,1000) or before[4] not in (0,1000) or before[5]!=1 or stat.S_IMODE(before[2])!=0o600 or not 0<before[6]<=limit:raise ValueError('claim_record_unsafe')\n  while True:\n   part=os.read(fd,min(65536,limit+1-len(raw)))\n   if not part:break\n   raw.extend(part)\n   if len(raw)>limit:raise ValueError('claim_record_limit')\n  record={'path':str(path),'state':'present','generation':before,'parents':parents,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'rawBase64':BASELINE_BASE64.b64encode(raw).decode()}\n  component_retirement_record_raw(record)\n  if len(raw)!=before[6] or COMPONENT_BUNDLE._pin(os.fstat(fd))!=before or COMPONENT_BUNDLE._pin(os.stat(path.name,dir_fd=chain[-1][1],follow_symlinks=False))!=before:raise ValueError('claim_record_changed')\n  return record\n finally:\n  if fd is not None:os.close(fd)\n  try:\n   for name,parent_fd in chain:\n    if COMPONENT_BUNDLE._pin(os.fstat(parent_fd))[:5]!=parents[name] or COMPONENT_BUNDLE._pin(os.stat(name,follow_symlinks=False))[:5]!=parents[name]:raise ValueError('claim_parent_changed')\n  finally:COMPONENT_BUNDLE._close(chain)"
