SESSION_TABLE_RECORD_RAW_SOURCE="def component_retirement_record_raw(record):\n # Called at the original producer's raw-before-parse point. Re-reading the\n # same immutable full record retains its original raw bytes once and emits\n # a typed reference. Any changed bytes/generation/ancestry are retained as a\n # NEW full record before subsequent checks can reject them.\n key=(record['path'],tuple(record['generation']),record['sha256'],record['bytes'],json.dumps(record['parents'],sort_keys=True))\n index=COMPONENT_RETIRE_RAW_INDEX.get(key)\n if index is None or COMPONENT_RETIRE_RAW_RECORDS[index]!=record:\n  if len(COMPONENT_RETIRE_RAW_RECORDS)>=512:raise ValueError('component_retirement_raw_inventory_limit')\n  index=len(COMPONENT_RETIRE_RAW_RECORDS);COMPONENT_RETIRE_RAW_RECORDS.append(record);COMPONENT_RETIRE_RAW_INDEX[key]=index\n CLAIM_OBSERVATIONS.append({'rawRecordReference':index,'path':record['path'],'generation':record['generation'],'sha256':record['sha256'],'bytes':record['bytes']})"
SESSION_TABLE_BIND_FACTORY='def bind_guarded_session_original_record(measurement):\n """Source-sealed retained intent record; existing current() rereads remain exact."""\n old="  opening_path=Path(original[\'backupPath\']);paths[\'opening-routing.json\']=opening_path"\n if measurement.count(old)!=1:raise ValueError(\'component_release_session_record_factory_changed\')\n bound="  READINESS_ORIGINAL_RECORDS[str(job/\'output/intent.json\')]=retained[\'output/intent.json\']\\n"\n result=measurement.replace(old,bound+old)\n compile(result,\'<fixed-original-session-record-binding>\',\'exec\')\n return result'
